import {createSeed,totals,donorTotal,entityName,potentialDuplicates,isoDay} from './domain.js';
import './style.css';

const seed=createSeed();let data;try{data=JSON.parse(localStorage.getItem('wildtrack-data'))||seed}catch{data=seed}
const routes=[['overview','Overview','◫','Workspace'],['donors','Donors','◉','Workspace'],['organisations','Organisations','▤','Workspace'],['contributions','Contributions','↗','Workspace'],['campaigns','Campaigns','◈','Workspace'],['events','Events','◷','Workspace'],['interactions','Interactions','↔','Relationships'],['followups','Follow-ups','☑','Relationships'],['grants','Grants','◇','Relationships'],['assistant','AI Assistant','✳','Intelligence'],['map','Relationship Map','⌘','Intelligence'],['insights','Insights & Reports','▥','Intelligence'],['data','Data Centre','⇅','Operations'],['integrations','Integrations','⛓','Operations'],['settings','Settings','⚙','Operations']];
let current=location.hash.slice(1)||'overview',query='',filter='All',sort='asc',selected=new Set(),importRows=[];
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n||0),date=s=>s?new Date(s+'T00:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'—';
function persist(){localStorage.setItem('wildtrack-data',JSON.stringify(data))}function go(route){current=route;location.hash=route;render()}
function toast(msg){const el=document.createElement('div');el.className='toast';el.textContent=msg;document.body.append(el);setTimeout(()=>el.remove(),2600)}
function donorName(d){return `${d.firstName} ${d.lastName}`}
function person(id){return data.donors.find(d=>d.id===id)}
function avatar(name){return `<span class="avatar">${esc(name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span>`}
function pageHead(title,desc,action=''){return `<div class="page-head"><div><div class="eyebrow">WILDTRACK / ${esc(current.toUpperCase())}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function button(label,action,cls='primary',icon=''){return `<button class="${cls}" data-action="${action}">${icon?`<span>${icon}</span> `:''}${label}</button>`}
function metric(label,value,detail,accent=''){return `<article class="metric ${accent}"><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-detail">${detail}</div></article>`}
function nav(){let group='';return routes.map(([id,label,icon,g])=>{const start=g!==group;group=g;return `${start?`<div class="nav-group">${g}</div>`:''}<a href="#${id}" class="nav-link ${current===id?'active':''}" data-route="${id}"><span class="nav-icon">${icon}</span><span>${label}</span>${id==='followups'&&totals(data).due?`<span class="nav-count">${totals(data).due}</span>`:''}</a>`}).join('')}
function shell(content){$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><div class="brand-mark">W</div><div><strong>WildTrack</strong><small>CWS FUNDRAISING</small></div><button class="collapse" aria-label="Collapse sidebar">☰</button></div><div class="workspace-switch"><span class="workspace-dot"></span><span>Conservation workspace</span><span class="chev">⌄</span></div><nav>${nav()}</nav><div class="side-bottom"><div class="data-note"><span class="dot"></span> Fictional demo data</div><button class="profile" data-action="profile">${avatar('Anika Rao')}<span><b>Anika Rao</b><small>Fundraising manager</small></span><span class="more">···</span></button></div></aside><main class="main"><header class="topbar"><div class="crumb"><span>Workspace</span><b>/</b><strong>${esc(routes.find(x=>x[0]===current)?.[1]||'Overview')}</strong></div><div class="top-actions"><label class="global-search"><span>⌕</span><input id="global-search" placeholder="Search anything..." value="${esc(query)}"><kbd>Ctrl K</kbd></label><button class="icon-btn" data-action="notifications" title="Notifications">♧<i></i></button><button class="icon-btn" data-action="help" title="Help">?</button><button class="mini-avatar" data-action="profile">AR</button></div></header><div class="content">${content}</div><footer>WildTrack prototype <span>•</span> Fictional sample records <span>•</span> Frontend only</footer></main><div id="overlay"></div><div id="toast-region" aria-live="polite"></div>`}
function overview(){const m=totals(data),bars=Array.from({length:7},(_,i)=>{const month=new Date();month.setMonth(month.getMonth()-6+i);const key=month.toISOString().slice(0,7);const amount=data.contributions.filter(c=>c.paymentStatus==='Completed'&&c.contributionDate.slice(0,7)===key).reduce((s,c)=>s+c.amount,0);return{label:month.toLocaleDateString('en',{month:'short'}),amount}}),max=Math.max(1,...bars.map(x=>x.amount));const due=data.tasks.filter(x=>x.status!=='Completed').sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).slice(0,5);const recent=[...data.interactions].sort((a,b)=>b.occurredAt.localeCompare(a.occurredAt)).slice(0,5);return `${pageHead('Good morning, Anika','A clear view of your relationships and next steps.',button('Add record','create','primary','＋'))}<section class="metric-grid">${metric('INDIVIDUAL DONORS',m.donors,'Across the workspace')}${metric('ORGANISATIONS',m.organisations,'Active relationships')}${metric('CONTRIBUTIONS · 30 DAYS',money(m.month),'Completed transactions','teal')}${metric('LIFETIME CONTRIBUTIONS',money(m.lifetime),'Completed · all sources')}${metric('FOLLOW-UPS DUE',m.due,`${m.overdue} overdue`,m.overdue?'amber':'')}${metric('ACTIVE CAMPAIGNS',m.activeCampaigns,'Currently fundraising')}</section><section class="dashboard-grid"><article class="panel chart-panel"><div class="panel-head"><div><h2>Contribution trends</h2><p>Completed contributions · last 7 months</p></div><span class="badge teal-badge">INR</span></div><div class="chart">${bars.map(b=>`<div class="bar-col"><span class="bar-value">${b.amount?Math.round(b.amount/1000)+'k':'—'}</span><div class="bar-track"><div class="bar" style="height:${Math.max(4,b.amount/max*100)}%"></div></div><span class="bar-label">${b.label}</span></div>`).join('')}</div></article><article class="panel attention-panel"><div class="panel-head"><div><h2>Needs attention</h2><p>Follow-ups to keep relationships moving</p></div><a href="#followups" data-route="followups">View all →</a></div>${due.map(t=>`<div class="task-row"><span class="priority p-${t.priority.toLowerCase()}"></span><div><b>${esc(t.title)}</b><small>${esc(entityName(data,t))} · ${date(t.dueDate)}</small></div><button class="check-btn" data-complete="${t.id}" title="Complete task">✓</button></div>`).join('')||'<div class="empty">No open follow-ups.</div>'}</article><article class="panel"><div class="panel-head"><div><h2>Recent relationship activity</h2><p>Latest logged interactions</p></div><a href="#interactions" data-route="interactions">All activity →</a></div>${recent.map(x=>`<div class="activity-row">${avatar(x.donorId?donorName(person(x.donorId)):entityName(data,x))}<div><b>${esc(x.subject)}</b><small>${esc(entityName(data,x))} · ${date(x.occurredAt)}</small></div><span class="type-pill">${esc(x.interactionType)}</span></div>`).join('')}</article><article class="panel"><div class="panel-head"><div><h2>Campaign pulse</h2><p>Progress based on attributed completed contributions</p></div><a href="#campaigns" data-route="campaigns">All campaigns →</a></div>${data.campaigns.filter(c=>c.status==='Active').slice(0,4).map(c=>{const raised=data.contributions.filter(x=>x.campaignId===c.id&&x.paymentStatus==='Completed').reduce((s,x)=>s+x.amount,0);return `<div class="campaign-row"><div><b>${esc(c.name)}</b><small>${money(raised)} of ${money(c.targetAmount)}</small></div><div class="progress"><i style="width:${Math.min(100,raised/c.targetAmount*100)}%"></i></div></div>`}).join('')}</article></section>`}
function tablePage(key,title,desc,rows,cols,addLabel='Add record'){const action=button(addLabel,'create','primary','＋');const search=`<div class="table-tools"><input class="table-search" id="table-search" placeholder="Search ${title.toLowerCase()}…" value="${esc(query)}"><select id="table-filter"><option>All</option>${(key==='donors'?['Active','Needs attention']:key==='followups'?['Open','Completed']:key==='contributions'?['Completed','Pending']:[]).map(x=>`<option ${filter===x?'selected':''}>${x}</option>`)}</select><button class="secondary" data-action="export">↓ Export CSV</button></div>`;let list=[...rows];if(query)list=list.filter(x=>JSON.stringify(x).toLowerCase().includes(query.toLowerCase()));if(filter!=='All')list=list.filter(x=>(x.status||x.paymentStatus)===filter);list.sort((a,b)=>String(a[cols[0]?.key]||'').localeCompare(String(b[cols[0]?.key]||''))*(sort==='asc'?1:-1));return `${pageHead(title,desc,action)}<section class="panel table-panel">${search}<div class="table-scroll"><table><thead><tr><th><input type="checkbox" id="select-all" aria-label="Select all"></th>${cols.map(c=>`<th data-sort="${c.key}" class="sortable">${c.label} ↕</th>`).join('')}<th></th></tr></thead><tbody>${list.slice(0,100).map(r=>`<tr><td><input type="checkbox" data-select="${r.id}" ${selected.has(r.id)?'checked':''}></td>${cols.map(c=>`<td>${c.render?c.render(r):esc(r[c.key])}</td>`).join('')}<td><button class="row-more" data-open="${key}:${r.id}" aria-label="Open record">···</button></td></tr>`).join('')||`<tr><td colspan="${cols.length+2}" class="empty">No matching records.</td></tr>`}</tbody></table></div><div class="table-foot">Showing ${Math.min(list.length,100)} of ${list.length} records <span>Sample data is fictional</span></div></section>`}
const donorCols=[{key:'firstName',label:'Donor',render:d=>`<button class="name-cell" data-open="donor:${d.id}">${avatar(donorName(d))}<span><b>${esc(donorName(d))}</b><small>${d.id}</small></span></button>`},{key:'email',label:'Email'},{key:'status',label:'Status',render:d=>`<span class="status ${d.status==='Needs attention'?'warn':''}">${esc(d.status)}</span>`},{key:'acquisitionSource',label:'Source'},{key:'interests',label:'Interests',render:d=>`<span class="interest">${esc(d.interests[0])}</span>`},{key:'total',label:'Lifetime giving',render:d=>money(donorTotal(data,d.id))},{key:'owner',label:'Owner',render:d=>`${avatar(d.owner)} ${esc(d.owner)}`}];
function donorProfile(id){const d=person(id);if(!d)return '';const contributions=data.contributions.filter(x=>x.donorId===id).sort((a,b)=>b.contributionDate.localeCompare(a.contributionDate));const interactions=data.interactions.filter(x=>x.donorId===id).sort((a,b)=>b.occurredAt.localeCompare(a.occurredAt));const tasks=data.tasks.filter(x=>x.donorId===id&&x.status!=='Completed');const first=contributions.at(-1);const next=tasks.sort((a,b)=>a.dueDate.localeCompare(b.dueDate))[0];return `${pageHead('Donor relationship','A consolidated, evidence-linked relationship history.',`<button class="secondary" data-action="edit-donor:${id}">Edit donor</button> ${button('Add interaction','create-interaction','primary','＋')} ${button('Create follow-up','create-task','secondary','＋')}`)}<section class="profile-card panel"><div class="profile-ident">${avatar(donorName(d))}<div><div class="eyebrow">${d.id} · INDIVIDUAL</div><h2>${esc(donorName(d))}</h2><div class="contact-line">${esc(d.email)} <span>·</span> ${esc(d.phone)}</div></div></div><div class="profile-meta"><span class="status ${d.status==='Needs attention'?'warn':''}">${esc(d.status)}</span><span>Owner <b>${esc(d.owner)}</b></span><span>Source <b>${esc(d.acquisitionSource)}</b></span></div><div class="chip-row">${d.interests.map(x=>`<span class="interest">${esc(x)}</span>`).join('')}<span class="interest">${esc(d.communicationPreferences)}</span></div></section><section class="metric-grid profile-metrics">${metric('LIFETIME CONTRIBUTIONS',money(donorTotal(data,id)),`${contributions.length} recorded gifts`)}${metric('FIRST CONTRIBUTION',date(first?.contributionDate),'Verified contribution record')}${metric('LAST INTERACTION',date(interactions[0]?.occurredAt),interactions[0]?.interactionType||'No interactions yet')}${metric('NEXT ACTION',next?date(next.dueDate):'None scheduled',next?next.title:'No open follow-up')}</section><div class="profile-tabs"><button class="tab active">Overview</button><button class="tab" data-action="profile-tab:timeline">Timeline (${interactions.length+contributions.length})</button><button class="tab" data-action="profile-tab:contributions">Contributions (${contributions.length})</button><button class="tab" data-action="profile-tab:tasks">Tasks (${tasks.length})</button></div><section class="profile-grid"><article class="panel"><div class="panel-head"><div><h2>Relationship timeline</h2><p>Verified records from shared workspace data</p></div><button class="text-btn" data-open="all-timeline:${id}">View full timeline →</button></div><div class="timeline">${[...interactions.slice(0,6).map(x=>({...x,_date:x.occurredAt,_kind:x.interactionType})),...contributions.slice(0,4).map(x=>({...x,_date:x.contributionDate,_kind:'Contribution',subject:`${money(x.amount)} · ${x.contributionType}`,description:`${x.paymentStatus} · ${x.sourceSystem}`,staffOwner:'Imported record'}))].sort((a,b)=>b._date.localeCompare(a._date)).slice(0,8).map(x=>`<div class="timeline-item"><i></i><div class="timeline-top"><b>${esc(x.subject||x._kind)}</b><span>${date(x._date)}</span></div><div>${esc(x.description||'')}</div><small>${esc(x._kind)} · ${esc(x.staffOwner||'Staff record')} · ${esc(x.sourceSystem||'Staff entry')}</small></div>`).join('')||'<div class="empty">No relationship history recorded.</div>'}</div></article><article class="panel"><h2>Relationship summary</h2><p>Verified stored information</p><dl class="facts"><dt>Recorded interests</dt><dd>${d.interests.map(esc).join(' · ')}</dd><dt>Communication preference</dt><dd>${esc(d.communicationPreferences)}</dd><dt>Acquisition source</dt><dd>${esc(d.acquisitionSource)}</dd><dt>Assigned relationship owner</dt><dd>${esc(d.owner)}</dd></dl><div class="ai-note"><span>✳</span><div><b>Suggested next action</b><p>${next?`Follow up on “${esc(next.title)}” by ${date(next.dueDate)}.`:'No pending follow-up is recorded. Consider logging a check-in after reviewing the timeline.'}</p><small>Derived from open follow-up records. Review before acting.</small></div></div><h3>Open follow-ups</h3>${tasks.map(t=>`<div class="task-row"><span class="priority p-${t.priority.toLowerCase()}"></span><div><b>${esc(t.title)}</b><small>Due ${date(t.dueDate)}</small></div><button class="check-btn" data-complete="${t.id}">✓</button></div>`).join('')||'<div class="empty">No open follow-ups.</div>'}</article></section>`}
function organisations(){const cols=[{key:'name',label:'Organisation',render:o=>`<button class="name-cell" data-open="org:${o.id}">${avatar(o.name)}<span><b>${esc(o.name)}</b><small>${o.id}</small></span></button>`},{key:'organisationType',label:'Type'},{key:'sector',label:'Sector'},{key:'partnershipStatus',label:'Partnership',render:o=>`<span class="status">${esc(o.partnershipStatus)}</span>`},{key:'owner',label:'Relationship owner'},{key:'contactIds',label:'Contacts',render:o=>`${o.contactIds.length} linked`}];return tablePage('organisations','Organisations','Institutional relationships, contacts and funding opportunities.',data.organisations,cols,'Add organisation')}
function contributions(){const cols=[{key:'id',label:'Contribution ID'},{key:'who',label:'Donor / organisation',render:x=>`<button class="text-btn" data-open="${x.donorId?'donor':'org'}:${x.donorId||x.organisationId}">${esc(entityName(data,x))}</button>`},{key:'amount',label:'Amount',render:x=>money(x.amount)},{key:'contributionDate',label:'Date',render:x=>date(x.contributionDate)},{key:'paymentStatus',label:'Payment',render:x=>`<span class="status ${x.paymentStatus==='Pending'?'warn':''}">${esc(x.paymentStatus)}</span>`},{key:'contributionType',label:'Type'},{key:'sourceSystem',label:'Source'},{key:'campaignId',label:'Campaign',render:x=>esc(data.campaigns.find(c=>c.id===x.campaignId)?.name||'—')}];return tablePage('contributions','Contributions','A transparent ledger of fictional, attributed giving.',data.contributions,cols,'Add contribution')}
function interactions(){const cols=[{key:'subject',label:'Interaction',render:x=>`<b>${esc(x.subject)}</b><small class="cell-sub">${esc(x.interactionType)}</small>`},{key:'related',label:'Relationship',render:x=>`<button class="text-btn" data-open="${x.donorId?'donor':'org'}:${x.donorId||x.organisationId}">${esc(entityName(data,x))}</button>`},{key:'occurredAt',label:'Date',render:x=>date(x.occurredAt)},{key:'staffOwner',label:'Owner'},{key:'outcome',label:'Outcome'},{key:'sourceSystem',label:'Source'}];return tablePage('interactions','Interactions','Emails, calls, meetings and notes linked to the relationship.',data.interactions,cols,'Log interaction')}
function followups(){const cols=[{key:'title',label:'Task',render:t=>`<div class="task-title"><span class="priority p-${t.priority.toLowerCase()}"></span><b>${esc(t.title)}</b></div>`},{key:'related',label:'Relationship',render:t=>`<button class="text-btn" data-open="${t.donorId?'donor':'org'}:${t.donorId||t.organisationId}">${esc(entityName(data,t))}</button>`},{key:'priority',label:'Priority'},{key:'dueDate',label:'Due date',render:t=>`<span class="${t.dueDate<isoDay(0)&&t.status!=='Completed'?'critical-text':''}">${date(t.dueDate)}</span>`},{key:'assignedTo',label:'Assigned to'},{key:'status',label:'Status',render:t=>`<span class="status ${t.status==='Completed'?'good':''}">${esc(t.status)}</span>`},{key:'complete',label:'',render:t=>t.status==='Completed'?'':`<button class="check-btn" data-complete="${t.id}">✓</button>`}];return tablePage('followups','Follow-up centre','Turn relationship commitments into clear, accountable next steps.',data.tasks,cols,'Create follow-up')}
function campaigns(){const rows=data.campaigns.map(c=>({...c,raised:data.contributions.filter(x=>x.campaignId===c.id&&x.paymentStatus==='Completed').reduce((s,x)=>s+x.amount,0)}));const cols=[{key:'name',label:'Campaign',render:c=>`<b>${esc(c.name)}</b><small class="cell-sub">${esc(c.objective)}</small>`},{key:'status',label:'Status',render:c=>`<span class="status">${esc(c.status)}</span>`},{key:'raised',label:'Raised',render:c=>money(c.raised)},{key:'targetAmount',label:'Target',render:c=>money(c.targetAmount)},{key:'progress',label:'Progress',render:c=>`<div class="progress compact"><i style="width:${Math.min(100,c.raised/c.targetAmount*100)}%"></i></div>`},{key:'startDate',label:'Starts',render:c=>date(c.startDate)},{key:'owner',label:'Owner'}];return tablePage('campaigns','Campaigns','Performance and giving attribution across conservation priorities.',rows,cols,'Create campaign')}
function events(){const rows=data.events.map(e=>({...e,attendees:data.interactions.filter(i=>i.eventId===e.id).length,raised:data.contributions.filter(c=>c.campaignId===e.campaignId).reduce((s,c)=>s+c.amount,0)}));return tablePage('events','Events','Participation, research briefings and related campaign activity.',rows,[{key:'name',label:'Event',render:e=>`<b>${esc(e.name)}</b><small class="cell-sub">${esc(e.location)}</small>`},{key:'eventDate',label:'Date',render:e=>date(e.eventDate)},{key:'status',label:'Status',render:e=>`<span class="status">${esc(e.status)}</span>`},{key:'campaignId',label:'Campaign',render:e=>esc(data.campaigns.find(c=>c.id===e.campaignId)?.name)},{key:'attendees',label:'Attendance records'},{key:'raised',label:'Attributed giving',render:e=>money(e.raised)}], 'Add event')}
function grants(){return tablePage('grants','Grants','Track institutional opportunities, deadlines and application progress.',data.grants,[{key:'title',label:'Opportunity'},{key:'organisationId',label:'Organisation',render:g=>esc(data.organisations.find(o=>o.id===g.organisationId)?.name)},{key:'amount',label:'Amount',render:g=>money(g.amount)},{key:'deadline',label:'Deadline',render:g=>date(g.deadline)},{key:'status',label:'Status',render:g=>`<span class="status">${esc(g.status)}</span>`},{key:'owner',label:'Owner'}],'Track grant')}
function assistant(){return `${pageHead('AI relationship assistant','Evidence-first retrieval from this workspace’s fictional records.', '<span class="mock-label">MOCK ASSISTANT · LOCAL DATA</span>')}<section class="assistant-layout"><article class="panel chat-panel"><div class="chat-head"><span class="assistant-mark">✳</span><div><b>WildTrack assistant</b><small>Answers cite records. Review recommendations before acting.</small></div><span class="status">No external AI connected</span></div><div class="chat-messages" id="chat-messages"><div class="chat-welcome"><span class="assistant-mark large">✳</span><h2>What would you like to know?</h2><p>I can retrieve facts from the records in this demo workspace.</p></div></div><div class="prompt-chips"><button data-prompt="Summarise a donor's relationship history">Donor history</button><button data-prompt="Which donors have overdue follow-ups?">Overdue follow-ups</button><button data-prompt="Find donors with recorded interest in tiger conservation">Tiger conservation</button><button data-prompt="Prepare a meeting briefing for an organisation">Organisation briefing</button></div><form id="chat-form" class="chat-input"><input id="chat-query" placeholder="Ask about recorded relationships…" autocomplete="off"><button class="primary">Send ↑</button></form></article><aside class="panel trust-panel"><h3>Trust and evidence</h3><div class="trust-item"><i class="fact"></i><div><b>Verified stored facts</b><p>Directly retrieved from sample records.</p></div></div><div class="trust-item"><i class="derived"></i><div><b>Derived summaries</b><p>Calculated from linked records.</p></div></div><div class="trust-item"><i class="recommend"></i><div><b>Recommendations</b><p>Suggestions require staff review.</p></div></div><div class="privacy-box">No donor information leaves this browser. This deterministic prototype has no connected language model and never contacts donors.</div></aside></section>`}
function answer(q){const l=q.toLowerCase();if(l.includes('overdue')){const ts=data.tasks.filter(t=>t.status!=='Completed'&&t.dueDate<isoDay(0));return{lead:`${ts.length} open follow-up${ts.length===1?'':'s'} are overdue.`,items:ts.slice(0,8).map(t=>`${entityName(data,t)} — ${t.title} (due ${date(t.dueDate)})`),source:'Follow-up records'}}if(l.includes('tiger')){const ds=data.donors.filter(d=>d.interests.some(i=>i.toLowerCase().includes('tiger')));return{lead:`${ds.length} donors have tiger conservation explicitly recorded as an interest.`,items:ds.slice(0,8).map(d=>`${donorName(d)} — ${d.id}; recorded interest: Tiger conservation`),source:'Donor profile interest fields'}}if(l.includes('organisation')||l.includes('briefing')){const o=data.organisations[0],cs=data.contributions.filter(c=>c.organisationId===o.id),is=data.interactions.filter(i=>i.organisationId===o.id);return{lead:`Briefing for ${o.name}: ${o.partnershipStatus.toLowerCase()} ${o.organisationType.toLowerCase()} relationship in ${o.sector}.`,items:[`Relationship owner: ${o.owner}`,`Linked contacts: ${o.contactIds.map(id=>donorName(person(id))).join(', ')}`,`Recorded contributions: ${cs.length} (${money(cs.reduce((s,c)=>s+c.amount,0))})`,`Recorded interactions: ${is.length}`],source:`${o.id}, linked contribution and interaction records`}}const d=data.donors.find(x=>l.includes(x.firstName.toLowerCase())||l.includes(x.id.toLowerCase()))||data.donors[0],cs=data.contributions.filter(c=>c.donorId===d.id).sort((a,b)=>b.contributionDate.localeCompare(a.contributionDate)),is=data.interactions.filter(i=>i.donorId===d.id).sort((a,b)=>b.occurredAt.localeCompare(a.occurredAt));return{lead:`${donorName(d)} (${d.id}) is an ${d.status.toLowerCase()} individual donor acquired through ${d.acquisitionSource}.`,items:[`Recorded interests: ${d.interests.join(', ')}`,`Completed contribution total: ${money(donorTotal(data,d.id))} across ${cs.length} records`,`Latest contribution: ${cs[0]?`${money(cs[0].amount)} on ${date(cs[0].contributionDate)}`:'None recorded'}`,`Latest interaction: ${is[0]?`${is[0].interactionType} · ${is[0].subject} · ${date(is[0].occurredAt)}`:'None recorded'}`,`Relationship owner: ${d.owner}`],source:`${d.id}, ${cs.slice(0,1).map(x=>x.id).join(', ')}, ${is.slice(0,1).map(x=>x.id).join(', ')}`}}
function insights(){const types=['Acquisition sources','Relationship activity','Data quality'];return `${pageHead('Insights & reports','Operational indicators calculated from shared sample data.',button('Export report','export','secondary','↓'))}<section class="metric-grid">${metric('DONOR RETENTION SIGNAL',`${Math.round(data.donors.filter(d=>data.contributions.some(c=>c.donorId===d.id)).length/data.donors.length*100)}%`,'Donors with a recorded contribution')}${metric('RECURRING CONTRIBUTIONS',data.contributions.filter(c=>c.contributionType==='Recurring').length,'Marked recurring in sample records')}${metric('FOLLOW-UP COMPLETION',`${Math.round(data.tasks.filter(t=>t.status==='Completed').length/data.tasks.length*100)}%`,'Completed tasks / all tasks')}${metric('DATA QUALITY FLAGS',data.contributions.filter(c=>c.reconciliationStatus==='Needs review').length,'Contributions awaiting reconciliation','amber')}</section><section class="dashboard-grid report-grid"><article class="panel"><h2>Donor acquisition</h2><p>Donor counts by recorded acquisition source</p>${sources.reduce((a,s)=>{const n=data.donors.filter(d=>d.acquisitionSource===s).length;a.push(`<div class="campaign-row"><div><b>${s}</b><small>${n} donors</small></div><div class="progress"><i style="width:${n/60*100}%"></i></div></div>`);return a},[]).join('')}</article><article class="panel"><h2>Relationship activity</h2><p>Logged interaction types</p>${['Email','Phone call','Meeting','Event attendance','Personal note'].map(t=>`<div class="campaign-row"><div><b>${t}</b><small>${data.interactions.filter(i=>i.interactionType===t).length} records</small></div></div>`).join('')}</article></section><p class="method-note">Retention signal is a descriptive count of donors with at least one contribution. It is not a statistically validated prediction. All figures derive from current browser data.</p>`}
function dataCentre(){return `${pageHead('Data centre','Unify exports with provenance and reviewable duplicate matching.','')}<section class="data-grid"><article class="panel import-panel"><div class="panel-head"><div><h2>Import records</h2><p>CSV files are parsed in this browser. No live source connection.</p></div><span class="status">Local preview</span></div><div class="dropzone"><div class="upload-icon">⇧</div><b>Choose a CSV file to preview</b><small>Flodesk, Razorpay, event attendance, or standard CSV</small><label class="primary upload-btn">Choose file<input id="csv-file" type="file" accept=".csv,text/csv"></label></div><div id="import-preview"></div></article><aside class="panel"><h2>Data quality</h2><p>Review records that need attention.</p>${[['Potential duplicate donors',potentialDuplicates([],data.donors).length],['Pending contributions',data.contributions.filter(c=>c.paymentStatus==='Pending').length],['Unmatched contributions',data.contributions.filter(c=>!c.donorId&&!c.organisationId).length],['Invalid donor emails',data.donors.filter(d=>!/^\S+@\S+\.\S+$/.test(d.email)).length]].map(([k,v])=>`<div class="quality-row"><span>${k}</span><b>${v}</b></div>`).join('')}<div class="privacy-box">Matching uses exact email or phone. Potential matches are shown for staff review; imports never silently merge a donor.</div></aside></section><section class="panel"><div class="panel-head"><div><h2>Import history</h2><p>Local jobs recorded in this browser session</p></div></div>${data.importJobs.length?data.importJobs.map(j=>`<div class="activity-row">${avatar('CSV')}<div><b>${esc(j.filename)}</b><small>${date(j.date)} · ${j.imported} imported · ${j.duplicates} possible duplicates</small></div><span class="status good">${j.status}</span></div>`).join(''):'<div class="empty">No imports yet. Upload a CSV to preview and map its columns.</div>'}</section>`}
function mapPage(){return `${pageHead('Relationship map','Explore meaningful links across donors, organisations, campaigns and activity.','')}<section class="panel map-panel"><div class="panel-head"><div><h2>Connected records</h2><p>Edges reflect stored relationships only</p></div><input id="map-search" placeholder="Find a donor or organisation…"><button class="secondary" data-action="map-reset">Reset</button></div><div id="map-content" class="map-content">${graph()}</div><div class="legend"><span><i class="node-d"></i> Donors</span><span><i class="node-o"></i> Organisations</span><span><i class="node-c"></i> Campaigns</span><span><i class="edge"></i> Recorded relationship</span></div></section>`}
function graph(){const ds=data.donors.slice(0,12);return `<div class="graph-area"><div class="graph-center">${data.campaigns.slice(0,4).map(c=>`<button class="graph-node node-camp" data-open="campaigns:${c.id}">${esc(c.name)}</button>`).join('')}</div><div class="graph-donors">${ds.map(d=>`<button class="graph-node node-donor" data-open="donor:${d.id}">${avatar(donorName(d))}<span>${esc(donorName(d))}</span></button>`).join('')}</div><div class="graph-orgs">${data.organisations.slice(0,6).map(o=>`<button class="graph-node node-org" data-open="org:${o.id}">${esc(o.name)}</button>`).join('')}</div></div>`}
function integrations(){return `${pageHead('Integrations','Honest connection status and clear future integration boundaries.','')}<section class="integration-grid">${[['Flodesk','Email engagement and acquisition exports','Ready for configuration','F'],['Razorpay','Contribution export reconciliation','Ready for configuration','R'],['CSV / Excel','Local file import preview is available','Mock connection','⇅'],['Event data sources','Attendance records via mapped CSV import','Ready for configuration','◷']].map(([n,d,s,i])=>`<article class="panel integration-card"><div class="integration-icon">${i}</div><div class="integration-title"><h2>${n}</h2><span class="status ${s==='Mock connection'?'warn':''}">${s}</span></div><p>${d}</p><div class="integration-foot"><span>Last sync <b>Never</b></span><button class="secondary" data-action="integration:${n}">Configure</button></div></article>`).join('')}</section><div class="privacy-box">No live API, webhook, or external account is connected. Integration status is not represented as connected.</div>`}
function settings(){return `${pageHead('Settings','Workspace preferences and prototype access controls.','')}<section class="settings-grid"><article class="panel"><h2>Workspace profile</h2><div class="settings-row"><label>Workspace name<input value="CWS Fundraising Workspace"></label><label>Timezone<select><option>Asia/Kolkata</option><option>UTC</option></select></label></div><button class="primary" data-action="save-settings">Save workspace settings</button></article><article class="panel"><h2>Team and roles</h2><p>Display roles only. Enforce real permissions in the future backend.</p>${owners.map((o,i)=>`<div class="activity-row">${avatar(o)}<div><b>${o}</b><small>${i===0?'Administrator':'Fundraising staff'} · Fictional account</small></div><span class="status">Active</span></div>`).join('')}</article><article class="panel"><h2>AI preferences</h2><p>Mock assistant uses local sample records only.</p><label class="switch-row"><span>Require review before record creation</span><input type="checkbox" checked disabled></label><label class="switch-row"><span>External model connection</span><span class="status">Not connected</span></label></article><article class="panel"><h2>Audit log</h2><p>Recent record changes made in this browser.</p>${data.audit.slice(-6).reverse().map(a=>`<div class="audit-row"><b>${esc(a.action)}</b><span>${esc(a.detail)}</span><small>${new Date(a.time).toLocaleString()}</small></div>`).join('')||'<div class="empty">No edits recorded yet.</div>'}</article></section>`}
const sources=['Website','Field event','Referral','Newsletter','Research briefing','Social media'];
function content(){if(current==='overview')return overview();if(current==='donors')return tablePage('donors','Donor directory','Search and manage individual relationships, giving and next actions.',data.donors.filter(d=>!d.archived),donorCols,'Add donor');if(current.startsWith('donor-'))return donorProfile(current.slice(6));if(current==='organisations')return organisations();if(current==='contributions')return contributions();if(current==='campaigns')return campaigns();if(current==='events')return events();if(current==='interactions')return interactions();if(current==='followups')return followups();if(current==='grants')return grants();if(current==='assistant')return assistant();if(current==='insights')return insights();if(current==='data')return dataCentre();if(current==='map')return mapPage();if(current==='integrations')return integrations();if(current==='settings')return settings();return overview()}
function render(){if(current.startsWith('donor:'))current='donor-'+current.slice(6);shell(content());}
function addAudit(action,detail){data.audit.push({action,detail,time:new Date().toISOString()});persist()}
function openModal(title,fields,onSave,existing={}){const fieldHtml=fields.map(f=>{const value=existing[f.key]??f.value??'';if(f.type==='select')return `<label>${f.label}<select name="${f.key}" ${f.required?'required':''}>${f.options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;if(f.type==='textarea')return `<label class="wide">${f.label}<textarea name="${f.key}" rows="3" ${f.required?'required':''}>${esc(value)}</textarea></label>`;return `<label>${f.label}<input name="${f.key}" type="${f.type||'text'}" value="${esc(value)}" ${f.required?'required':''} ${f.type==='email'?'pattern="[^ @]+@[^ @]+\\.[^ @]+"':''}></label>`}).join('');$('#overlay').innerHTML=`<div class="scrim" data-dismiss="true"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header><div><span class="eyebrow">WILDTRACK RECORD</span><h2>${title}</h2></div><button class="icon-btn" data-action="close">×</button></header><form id="record-form"><div class="form-grid">${fieldHtml}</div><div class="form-error" id="form-error"></div><footer><button type="button" class="secondary" data-action="close">Cancel</button><button class="primary">Save record</button></footer></form></section></div>`;$('#record-form').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.currentTarget),out=Object.fromEntries(fd.entries());for(const f of fields)if(f.required&&!out[f.key]){$('#form-error').textContent=`${f.label} is required.`;return}onSave(out)};}
function fieldsFor(type){const donorOptions=data.donors.map(d=>donorName(d)),orgOptions=data.organisations.map(o=>o.name),campOptions=data.campaigns.map(c=>c.name),commonOwner={key:'owner',label:'Relationship owner',type:'select',options:owners};switch(type){case'donor':return[{key:'firstName',label:'First name',required:true},{key:'lastName',label:'Last name',required:true},{key:'email',label:'Email',type:'email',required:true},{key:'phone',label:'Phone'},{key:'acquisitionSource',label:'Acquisition source',type:'select',options:sources},{key:'interests',label:'Conservation interests (comma separated)',value:'Wildlife research'},{key:'status',label:'Status',type:'select',options:['Active','Needs attention','Paused']},commonOwner];case'organisation':return[{key:'name',label:'Organisation name',required:true},{key:'organisationType',label:'Organisation type',type:'select',options:['Foundation','Corporate partner','Research institution','Nonprofit']},{key:'sector',label:'Sector'},{key:'website',label:'Website'},{key:'address',label:'Address'},{key:'partnershipStatus',label:'Partnership status',type:'select',options:['Prospect','In discussion','Active','Paused']},commonOwner];case'interaction':return[{key:'donorName',label:'Individual donor',type:'select',options:['—',...donorOptions]},{key:'organisationName',label:'Organisation',type:'select',options:['—',...orgOptions]},{key:'interactionType',label:'Type',type:'select',options:['Email','Phone call','Meeting','Event attendance','Personal note','Other']},{key:'subject',label:'Subject',required:true},{key:'description',label:'Description',type:'textarea',required:true},{key:'outcome',label:'Outcome'},{key:'occurredAt',label:'Date',type:'date',value:isoDay(0)},{key:'staffOwner',label:'Staff owner',type:'select',options:owners}];case'task':return[{key:'title',label:'Task title',required:true},{key:'donorName',label:'Individual donor',type:'select',options:['—',...donorOptions]},{key:'organisationName',label:'Organisation',type:'select',options:['—',...orgOptions]},{key:'priority',label:'Priority',type:'select',options:['High','Medium','Low']},{key:'dueDate',label:'Due date',type:'date',value:isoDay(7)},{key:'assignedTo',label:'Assigned to',type:'select',options:owners},{key:'description',label:'Description',type:'textarea'}];case'contribution':return[{key:'donorName',label:'Individual donor',type:'select',options:['—',...donorOptions]},{key:'organisationName',label:'Organisation',type:'select',options:['—',...orgOptions]},{key:'amount',label:'Amount (INR)',type:'number',required:true},{key:'contributionDate',label:'Date',type:'date',value:isoDay(0)},{key:'contributionType',label:'Type',type:'select',options:['One-time','Recurring','Pledge','Sponsorship','Grant funding']},{key:'paymentMethod',label:'Payment method',type:'select',options:['Bank transfer','UPI','Card','Cheque']},{key:'campaignName',label:'Campaign',type:'select',options:campOptions},{key:'externalReference',label:'External reference'}];case'campaign':return[{key:'name',label:'Campaign name',required:true},{key:'objective',label:'Objective',type:'textarea'},{key:'targetAmount',label:'Target amount',type:'number',required:true},{key:'startDate',label:'Start date',type:'date',value:isoDay(0)},{key:'endDate',label:'End date',type:'date',value:isoDay(90)},{key:'owner',label:'Owner',type:'select',options:owners}];case'event':return[{key:'name',label:'Event name',required:true},{key:'description',label:'Description',type:'textarea'},{key:'eventDate',label:'Event date',type:'date',value:isoDay(30)},{key:'location',label:'Location'},{key:'campaignName',label:'Campaign',type:'select',options:campOptions}];case'grant':return[{key:'title',label:'Opportunity',required:true},{key:'organisationName',label:'Grant organisation',type:'select',options:orgOptions},{key:'amount',label:'Amount',type:'number'},{key:'deadline',label:'Deadline',type:'date',value:isoDay(45)},{key:'status',label:'Status',type:'select',options:['Researching','Eligible','Preparing','Submitted','Under review','Approved','Rejected','Closed']},{key:'owner',label:'Owner',type:'select',options:owners},{key:'notes',label:'Notes',type:'textarea'}]}}
function create(type){const mapping={donor:'donor',organisation:'organisation',interaction:'interaction',task:'task',contribution:'contribution',campaign:'campaign',event:'event',grant:'grant'};if(type==='create')type=({donors:'donor',organisations:'organisation',contributions:'contribution',campaigns:'campaigns',events:'event',interactions:'interaction',followups:'task',grants:'grant'})[current]||'donor';if(type==='interaction')type='interaction';if(type==='create-interaction')type='interaction';if(type==='create-task')type='task';if(type==='campaigns')type='campaign';if(!mapping[type])type='donor';openModal(({donor:'Add individual donor',organisation:'Add organisation',interaction:'Log interaction',task:'Create follow-up',contribution:'Add contribution',campaign:'Create campaign',event:'Create event',grant:'Track grant'})[type],fieldsFor(type),out=>{const id=kind=>`${kind}-${Math.random().toString(36).slice(2,8).toUpperCase()}`,byName=n=>n&&n!=='—'?data.donors.find(d=>donorName(d)===n)?.id:null,byOrg=n=>data.organisations.find(o=>o.name===n)?.id;let row;if(type==='donor'){row={id:id('D'),...out,interests:out.interests.split(',').map(x=>x.trim()).filter(Boolean),createdAt:isoDay(0),archived:false,communicationPreferences:'Email'};data.donors.unshift(row)}else if(type==='organisation'){row={id:id('O'),...out,contactIds:[]};data.organisations.unshift(row)}else if(type==='interaction'){row={id:id('I'),...out,donorId:byName(out.donorName),organisationId:byOrg(out.organisationName),occurredAt:out.occurredAt,sourceSystem:'Staff entry',followUpRequired:false};delete row.donorName;delete row.organisationName;data.interactions.unshift(row)}else if(type==='task'){row={id:id('T'),...out,donorId:byName(out.donorName),organisationId:byOrg(out.organisationName),status:'Open'};delete row.donorName;delete row.organisationName;data.tasks.unshift(row)}else if(type==='contribution'){row={id:id('G'),...out,amount:Number(out.amount),currency:'INR',paymentStatus:'Completed',campaignId:data.campaigns.find(c=>c.name===out.campaignName)?.id,sourceSystem:'Staff entry',reconciliationStatus:'Matched'};row.donorId=byName(out.donorName);row.organisationId=byOrg(out.organisationName);delete row.donorName;delete row.organisationName;delete row.campaignName;if(Boolean(row.donorId)===Boolean(row.organisationId)){$('#form-error').textContent='Select exactly one individual donor or organisation.';return}data.contributions.unshift(row)}else if(type==='campaign'){row={id:id('C'),...out,targetAmount:+out.targetAmount,status:'Active'};data.campaigns.unshift(row)}else if(type==='event'){row={id:id('E'),...out,campaignId:data.campaigns.find(c=>c.name===out.campaignName)?.id,status:'Upcoming'};delete row.campaignName;data.events.unshift(row)}else{row={id:id('GR'),...out,amount:+out.amount,organisationId:byOrg(out.organisationName)};delete row.organisationName;data.grants.unshift(row)}addAudit(`Created ${type}`,row.id);persist();$('#overlay').innerHTML='';toast('Record saved to this workspace');if(type==='donor')current='donors';render()})}
function editDonor(id){const d=person(id);openModal('Edit donor',fieldsFor('donor'),out=>{Object.assign(d,out,{interests:out.interests.split(',').map(x=>x.trim()).filter(Boolean)});addAudit('Updated donor',d.id);persist();$('#overlay').innerHTML='';toast('Donor profile updated');render()}, {...d,interests:d.interests.join(', ')})}
function openOrganisation(id){const o=data.organisations.find(x=>x.id===id);if(!o)return;const linked=data.contributions.filter(c=>c.organisationId===id),its=data.interactions.filter(i=>i.organisationId===id),gs=data.grants.filter(g=>g.organisationId===id);$('#overlay').innerHTML=`<div class="scrim" data-dismiss="true"><section class="drawer" role="dialog" aria-modal="true"><header><div><span class="eyebrow">${o.id} · ORGANISATION</span><h2>${esc(o.name)}</h2><p>${esc(o.organisationType)} · ${esc(o.sector)}</p></div><button class="icon-btn" data-action="close">×</button></header><div class="drawer-content"><div class="profile-meta"><span class="status">${esc(o.partnershipStatus)}</span><span>Owner <b>${esc(o.owner)}</b></span></div><p>${esc(o.address)} · <a target="_blank" rel="noreferrer" href="${esc(o.website)}">${esc(o.website)}</a></p><h3>Key contacts</h3>${o.contactIds.map(id=>{const d=person(id);return d?`<button class="name-cell" data-open="donor:${id}">${avatar(donorName(d))}<span><b>${esc(donorName(d))}</b><small>${esc(d.email)}</small></span></button>`:''}).join('')}<h3>Funding history</h3>${linked.map(c=>`<div class="activity-row"><b>${money(c.amount)}</b><span>${date(c.contributionDate)} · ${esc(c.contributionType)}</span></div>`).join('')||'<p>No contribution records.</p>'}<h3>Grant opportunities</h3>${gs.map(g=>`<div class="activity-row"><b>${esc(g.title)}</b><span>${money(g.amount)} · ${esc(g.status)} · ${date(g.deadline)}</span></div>`).join('')||'<p>No grant opportunities.</p>'}<h3>Recent meetings and interactions</h3>${its.slice(0,5).map(i=>`<div class="timeline-item"><b>${esc(i.subject)}</b><span>${date(i.occurredAt)} · ${esc(i.interactionType)}</span></div>`).join('')||'<p>No interactions.</p>'}</div><footer><button class="secondary" data-action="edit-org:${id}">Edit organisation</button><button class="primary" data-action="close">Done</button></footer></section></div>`}
function exportCsv(){let rows,headers;if(current==='donors'){headers=['id','firstName','lastName','email','phone','acquisitionSource','interests','owner','status'];rows=data.donors}else if(current==='contributions'){headers=['id','donorId','organisationId','amount','currency','contributionDate','paymentMethod','paymentStatus','contributionType','campaignId','externalReference','sourceSystem'];rows=data.contributions}else{headers=['id','title','status','dueDate','assignedTo'];rows=data.tasks}const csv=[headers.join(','),...rows.map(r=>headers.map(h=>`"${String(Array.isArray(r[h])?r[h].join('; '):r[h]??'').replaceAll('"','""')}"`).join(','))].join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=`wildtrack-${current}.csv`;a.click();URL.revokeObjectURL(a.href);toast('CSV export downloaded')}
function parseCsv(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){cell+='"';i++}else if(c==='"')quoted=false;else cell+=c}else if(c==='"')quoted=true;else if(c===','){row.push(cell);cell=''}else if(c==='\n'){row.push(cell.replace(/\r$/,''));rows.push(row);row=[];cell=''}else cell+=c}if(cell||row.length){row.push(cell);rows.push(row)}const headers=(rows.shift()||[]).map(x=>x.trim());return rows.filter(r=>r.some(Boolean)).map(r=>Object.fromEntries(headers.map((h,i)=>[h,(r[i]||'').trim()])))}
function showImport(rows,name){importRows=rows;const required=['firstName','lastName','email'];const invalid=rows.filter(r=>!r.firstName||!r.lastName||!/^\S+@\S+\.\S+$/.test(r.email||'')).length;const duplicates=potentialDuplicates(rows,data.donors);$('#import-preview').innerHTML=`<div class="preview-head"><div><h3>Preview: ${esc(name)}</h3><p>${rows.length} rows · ${invalid} validation issues · ${duplicates.length} potential duplicates</p></div><button class="secondary" data-action="clear-import">Clear</button></div><div class="mapping-grid">${required.map(key=>`<label>Map ${key}<select data-map="${key}"><option value="">Choose column</option>${Object.keys(rows[0]||{}).map(k=>`<option value="${esc(k)}" ${k.toLowerCase()===key.toLowerCase()?'selected':''}>${esc(k)}</option>`).join('')}</select></label>`).join('')}</div><div class="table-scroll"><table><thead><tr>${Object.keys(rows[0]||{}).map(h=>`<th>${esc(h)}</th>`).join('')}<th>Match review</th></tr></thead><tbody>${rows.slice(0,8).map((r,i)=>`<tr>${Object.values(r).map(v=>`<td>${esc(v)}</td>`).join('')}<td>${duplicates.some(d=>d.index===i)?`Potential match: ${esc(duplicates.find(d=>d.index===i).match.email)}`:'No exact match'}</td></tr>`).join('')}</tbody></table></div><div class="privacy-box">Potential matches are never merged. Rows with missing names or invalid emails will be skipped.</div><button class="primary" data-action="confirm-import" data-file="${esc(name)}">Import unmatched valid donors</button>`}
function confirmImport(name){const mapping=Object.fromEntries([...document.querySelectorAll('[data-map]')].map(s=>[s.dataset.map,s.value]));if(Object.values(mapping).some(x=>!x)){toast('Map first name, last name and email before importing');return}const duplicateIndexes=new Set(potentialDuplicates(importRows.map(r=>({email:r[mapping.email],phone:r.phone})),data.donors).map(x=>x.index));let count=0,rejected=0,dupes=0;for(const r of importRows){const firstName=r[mapping.firstName],lastName=r[mapping.lastName],email=r[mapping.email];if(!firstName||!lastName||!/^\S+@\S+\.\S+$/.test(email||'')){rejected++;continue}if(duplicateIndexes.has(importRows.indexOf(r))){dupes++;continue}data.donors.push({id:`D-IMP-${Date.now().toString(36)}-${count}`,firstName,lastName,email,phone:r.phone||'',acquisitionSource:'CSV import',interests:[],owner:'Anika Rao',status:'Active',communicationPreferences:'Email',createdAt:isoDay(0),sourceProvenance:name,archived:false});count++}data.importJobs.unshift({filename:name,date:isoDay(0),imported:count,duplicates:dupes,rejected,status:'Completed'});addAudit('Imported CSV',`${name}: ${count} imported, ${dupes} potential duplicates, ${rejected} rejected`);persist();toast(`${count} donors imported; ${dupes} possible duplicates skipped`);render()}
function assistantAsk(text){if(!text.trim())return;const msgs=$('#chat-messages');if(msgs.querySelector('.chat-welcome'))msgs.innerHTML='';const u=document.createElement('div');u.className='chat-bubble user-bubble';u.textContent=text;msgs.append(u);const result=answer(text),a=document.createElement('div');a.className='chat-bubble assistant-bubble';a.innerHTML=`<p>${esc(result.lead)}</p><ul>${result.items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="source-ref">Evidence: ${esc(result.source)} · <span>Retrieved from workspace records</span></div>`;msgs.append(a);msgs.scrollTop=msgs.scrollHeight;}
document.addEventListener('click',e=>{const route=e.target.closest('[data-route]');if(route){e.preventDefault();go(route.dataset.route);return}const opened=e.target.closest('[data-open]');if(opened){const [kind,id]=opened.dataset.open.split(':');if(kind==='donor')go(`donor-${id}`);else if(kind==='org')openOrganisation(id);else if(kind==='all-timeline'){const donor=person(id);go('donors');toast(`Timeline records for ${donorName(donor)} are shown in their profile.`)}else if(kind==='campaigns')go('campaigns');return}const complete=e.target.closest('[data-complete]');if(complete){const t=data.tasks.find(x=>x.id===complete.dataset.complete);if(t){t.status='Completed';addAudit('Completed follow-up',t.id);persist();toast('Follow-up completed');render()}return}const action=e.target.closest('[data-action]')?.dataset.action;if(action){if(action==='create'||action.startsWith('create-'))create(action);else if(action==='close')$('#overlay').innerHTML='';else if(action.startsWith('edit-donor:'))editDonor(action.split(':')[1]);else if(action.startsWith('edit-org:'))toast('Organisation edits can be added from the organisation form.');else if(action==='export')exportCsv();else if(action==='clear-import'){importRows=[];render()}else if(action==='map-reset'){$('#map-search').value='';$('#map-content').innerHTML=graph()}else if(action==='notifications')toast(`${totals(data).due} follow-ups need attention`);else if(action==='help')toast('Use Ctrl+K to search records and navigate.');else if(action==='profile')go('settings');else if(action==='save-settings')toast('Workspace settings saved locally');else if(action==='confirm-import')confirmImport(e.target.dataset.file);else if(action.startsWith('integration:'))toast('No external connection is configured. Import an export file in Data Centre.');else if(action.startsWith('profile-tab:'))toast(`Use the linked history panel to review ${action.split(':')[1]}.`);return}const prompt=e.target.closest('[data-prompt]');if(prompt){assistantAsk(prompt.dataset.prompt);return}if(e.target.matches('.scrim'))$('#overlay').innerHTML='';});
document.addEventListener('input',e=>{if(e.target.id==='global-search'){query=e.target.value;if(query.length>1)showCommandSearch(query)}if(e.target.id==='table-search'){query=e.target.value;const pos=e.target.selectionStart;render();const n=$('#table-search');if(n){n.focus();n.setSelectionRange(pos,pos)}}if(e.target.id==='map-search'){const q=e.target.value.toLowerCase();const nodes=[...document.querySelectorAll('.graph-node')];nodes.forEach(n=>n.classList.toggle('dim',q&&!n.textContent.toLowerCase().includes(q)))}});
document.addEventListener('change',e=>{if(e.target.id==='table-filter'){filter=e.target.value;render()}if(e.target.id==='select-all'){document.querySelectorAll('[data-select]').forEach(x=>{x.checked=e.target.checked; x.checked?selected.add(x.dataset.select):selected.delete(x.dataset.select)})}if(e.target.matches('[data-select]'))e.target.checked?selected.add(e.target.dataset.select):selected.delete(e.target.dataset.select);if(e.target.id==='csv-file'&&e.target.files[0]){const f=e.target.files[0];const reader=new FileReader();reader.onload=()=>{try{const rows=parseCsv(reader.result);if(!rows.length)throw Error('No rows found');showImport(rows,f.name)}catch(err){toast(`Could not parse CSV: ${err.message}`)}};reader.readAsText(f)}if(e.target.dataset.sort){sort=sort==='asc'?'desc':'asc';render()}});
document.addEventListener('click',e=>{if(e.target.matches('[data-sort]')){sort=sort==='asc'?'desc':'asc';render()}});
document.addEventListener('submit',e=>{if(e.target.id==='chat-form'){e.preventDefault();assistantAsk($('#chat-query').value);$('#chat-query').value=''}});
function showCommandSearch(q){let box=$('#command-results');if(!box){box=document.createElement('div');box.id='command-results';box.className='command-results';$('.topbar').append(box)}const l=q.toLowerCase();const hits=[...data.donors.filter(d=>donorName(d).toLowerCase().includes(l)||d.email.toLowerCase().includes(l)).slice(0,5).map(d=>({name:donorName(d),sub:'Donor · '+d.id,run:()=>go('donor-'+d.id)})),...data.organisations.filter(o=>o.name.toLowerCase().includes(l)).slice(0,3).map(o=>({name:o.name,sub:'Organisation',run:()=>openOrganisation(o.id)})),...routes.filter(r=>r[1].toLowerCase().includes(l)).slice(0,4).map(r=>({name:r[1],sub:'Navigate',run:()=>go(r[0])}))];box.innerHTML=hits.length?hits.map((h,i)=>`<button data-cmd="${i}"><b>${esc(h.name)}</b><small>${esc(h.sub)}</small></button>`).join(''):'<div class="empty">No matching records</div>';box._hits=hits;box.querySelectorAll('[data-cmd]').forEach(b=>b.onclick=()=>{box._hits[b.dataset.cmd].run();box.remove()})}
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search').focus();$('#global-search').select()}if(e.key==='Escape'){$('#overlay').innerHTML='';$('#command-results')?.remove()}if(e.key==='Enter'&&document.activeElement===$('#global-search')){const first=$('#command-results button');if(first)first.click()}});
window.addEventListener('hashchange',()=>{current=location.hash.slice(1)||'overview';query='';render()});render();
